long CBaseRenderer::BreakConnect()
{
    // Do we have a quality management sink

    if (m_pQSink) {
        m_pQSink->Release();
        m_pQSink = 0;
    }

    // Check we have a valid connection

    if (m_pInputPin->IsConnected() == 0) {
